python -c "
import toolz
from toolz.functoolz import num_required_args, has_keywords

def should_curry(func):
    if not callable(func) or isinstance(func, toolz.curry):
        return False
    nargs = num_required_args(func)
    if nargs is None or nargs > 1:
        return True
    return nargs == 1 and has_keywords(func)

print('num_required_args(get_config_from_root):', num_required_args(toolz.get_config_from_root))
print('should_curry:', should_curry(toolz.get_config_from_root))
"
